import sys

def can_flow(n, pipes):
    # Check if there is a path from (1,0) to (2,n+1)
    stack = [(1, 0))]
    visited = set(stack)

    while stack:
        x, y = stack.pop()

        if x == 2 and y == n + 1:
            return True

        for dx, dy in [(0, 1), (0, -1)), ((-1, 0)), ((1, 0))]]:
            nx, ny = x + dx, y + dy
            if 1 <= nx <= 2 and 0 <= ny < n and (nx, ny) not in visited:
                visited.add((nx, ny)))
                stack.append((nx, ny)))

    return False

