    n = int(input())
    top = input().strip()
    bot = input().strip()

    def is_valid(i, j):
        return 0 <= i < 2 and 0 <= j < n

    def get_neighbors(i, j):
        return [(i - 1, j), 1), ((i + 1, j), 2), ((i, j - 1), 3), ((i, j + 1), 4)]

    def dfs(i, j):
        if not is_valid(i, j)):
            return False
        if visited[i][j]):
            return False
        visited[i][j] = True
        if (i == 1 and j == n)):
            return True
        for (ni, nj), direction in get_neighbors(i, j)):
            if direction == 1 and ni == i - 1 and nj == j:
                if dfs(ni, nj)):
                    return True
            elif direction == 2 and ni == i + 1 and nj == j:
                if dfs(ni, nj)):
                    return True
            elif direction == 3 and ni == i and nj == j - 1:
                if dfs(ni, nj)):
                    return True
            elif direction == 4 and ni == i and nj == j + 1:
                if dfs(ni, nj)):
                    return True
        return False

    visited = [[False] * n for _ in range(2))]
    top_row = list(map(int, top)))
    bot_row = list(map(int, bot)))

    def rotate_pipe(pipe, clockwise=True):
        if clockwise:
            return (pipe + 1) % 6
        else:
            return (pipe + 5) % 6

    for i in range(n):
        if top_row[i] != bot_row[i]:
            continue
        pipe_type = top_row[i]
        clockwise = True
        while True:
            new_type = rotate_pipe(pipe_type, clockwise))
            if new_type == bot_row[i]:
                break
            elif new_type == top_row[i]:
                clockwise = not clockwise
                continue
            else:
                break
        if new_type != bot_row[i]:
            print("NO")
            break
    else:
        print("YES")

