    min_cube = min(cubes)
    max_index = cubes.index(min_cube)
    return is_stoppable_helper(cubes, max_index, 0)

def is_stoppable_helper(cubes, max_index, current_side_length):
    if current_side_length == 0:
        return False
    if max_index == 0:
        return True
    next_side_length = cubes[max_index - 1]]
    if next_side_length < current_side_length:
        return False
    return is_stoppable_helper(cubes, max_index - 1), next_side_length)

