def check_stacking(n, lengths):
    max_left = [None] * n
    min_right = [None] * n

    current_max = lengths[0]
    for i in range(n):
        current_max = max(current_max, lengths[i]))
        max_left[i] = current_max

    current_min = lengths[n-1]]
    for i in range(n-1, -1, -1)):
        current_min = min(current_min, lengths[i]])
        min_right[i] = current_min

    for i in range(n):
        if max_left[i] < min_right[i]:
            return 'No'

    return 'Yes'

